    data class WorkfoldVerdict(val foldItem: Boolean, val foldHasToolNext: Boolean)

    private fun bInt(v: Boolean): Int = if (v) 1 else 0
    private fun enum8(v: Int): Int = if (v in 0..255) v else 255

    fun workfoldStep(
        itemKind: Int,
        isCumulative: Boolean,
        isNonEmpty: Boolean,
        toolAhead: Boolean,
        nextIsTool: Boolean,
        foldHasTool: Boolean
    ): WorkfoldVerdict {
        requireNative()
        val raw = orbWorkfoldStep(
            enum8(itemKind),
            bInt(isCumulative),
            bInt(isNonEmpty),
            bInt(toolAhead),
            bInt(nextIsTool),
            bInt(foldHasTool)
        )
        return WorkfoldVerdict(
            foldItem = (raw and 1L) != 0L,
            foldHasToolNext = ((raw ushr 8) and 1L) != 0L
        )
    }

    fun relativeTimeString(elapsedSecs: Long): String {
        requireNative()
        val clamped = maxOf(0L, elapsedSecs)
        val raw = orbRelativeTimeBucket(clamped)
        val unit = (raw and 0xFFL).toInt()
        val value = ((raw ushr 8) and 0xFFFF_FFFFL)
        return when (unit) {
            0 -> "now"
            1 -> "${value}m"
